/* Overrides Chirpy's caching service worker.
   Browsers update an installed worker only when this script changes.
   With caching disabled, Chirpy still serves the previous sw.min.js, so
   return visits keep receiving cached pages. This script takes over,
   deletes every cache, reloads open pages, and unregisters. */
self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      const windows = await self.clients.matchAll({
        type: 'window',
        includeUncontrolled: true
      });
      await Promise.all(
        windows.map((client) => {
          if (client.url && typeof client.navigate === 'function') {
            return client.navigate(client.url);
          }
          return undefined;
        })
      );
      await self.registration.unregister();
    })()
  );
});
